// OO approach: model real-world entities
public class Loan {
    private double rate;
    private int years;
    private double amount;

    public double getMonthlyPayment() {
        double monthlyRate = rate / 1200;
        return amount * monthlyRate /
            (1 - Math.pow(1 / (1 + monthlyRate), years * 12));
    }
}
